int divide(int dividend, int divisor) {
    if (dividend == INT_MIN && divisor == -1) return INT_MAX;
    long a = labs(dividend), b = labs(divisor);
    long ans = 0;
    int sign = (dividend > 0) ^ (divisor > 0) ? -1 : 1;
    while (a >= b) {
        long temp = b, shift = 1;
        while (a >= (temp << 1)) {
            temp <<= 1; shift <<= 1;
        }
        a -= temp;
        ans += shift;
    }
    return ans * sign;
}
// 位移除法：每次找最大的2^k*divisor ≤ dividend | 用long防溢出
